def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")
    stack = []
    group = []
    for char in paren_string:
        if char == '(':
            group.append(char)
            stack.append(len(group) - 1)
        elif char == ')':
            start = stack.pop()
            end = len(group)
            while start + 1 < end:
                group[start] = group[start] + group[end - 1]
                group.pop()
                end -= 1
            group[start] = group[start] + ')'
    return group

